package app.kinnect.audit;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import android.graphics.*;import android.graphics.drawable.*;import java.lang.reflect.*;import java.io.*;
public class BrandAudit extends Instrumentation {
 private void checkText(View v){if(v instanceof TextView&&((TextView)v).getText().toString().contains("Kết nối theo"))throw new AssertionError("Startup tagline remains");if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++)checkText(g.getChildAt(i));}}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();try{
 Activity a=startActivitySync(new Intent().setClassName("app.kinnect.live","app.kinnect.live.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1500);
 runOnMainSync(()->{try{Method m=a.getClass().getDeclaredMethod("splash");m.setAccessible(true);m.invoke(a);checkText(a.getWindow().getDecorView());for(int size:new int[]{34,96,192}){Drawable d=a.getResources().getDrawable(a.getResources().getIdentifier("kinnect_logo","drawable",a.getPackageName()));Bitmap b=Bitmap.createBitmap(size,size,Bitmap.Config.ARGB_8888);d.setBounds(0,0,size,size);d.draw(new Canvas(b));if(Color.alpha(b.getPixel(0,0))!=0||Color.alpha(b.getPixel(size-1,size-1))!=0)throw new AssertionError("Logo corners are square at "+size);int k=b.getPixel(Math.round(size*60f/192),size/2);if(Color.red(k)<245||Color.green(k)<245||Color.blue(k)<245)throw new AssertionError("K is not white");}Drawable icon=a.getPackageManager().getApplicationIcon(a.getPackageName());Bitmap b=Bitmap.createBitmap(192,192,Bitmap.Config.ARGB_8888);icon.setBounds(0,0,192,192);icon.draw(new Canvas(b));if(Color.alpha(b.getPixel(0,0))!=0)throw new AssertionError("Launcher icon is square");}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();Thread.sleep(200);
 File shot=new File(a.getExternalFilesDir(null),"brand-splash.png");try(FileOutputStream out=new FileOutputStream(shot)){getUiAutomation().takeScreenshot().compress(Bitmap.CompressFormat.PNG,100,out);}result.putString("result","PASS: rounded corners at 34/96/192px, white K, rounded application icon, startup tagline removed");result.putString("screenshot",shot.getAbsolutePath());finish(Activity.RESULT_OK,result);
 }catch(Throwable t){result.putString("error",t.toString());finish(Activity.RESULT_CANCELED,result);}}
}
